private let tellomiBundledLocalizationTable: [String: [String: String]] = {
    var table: [String: [String: String]] = [:]
    for (code, blob) in tellomiBundledLocalizationBlobs {
        guard let data = blob.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: String] else {
            continue
        }
        table[code] = object
    }
    return table
}()

public func tellomiCanonicalLangPackCode(_ languageCode: String) -> String {
    let code = languageCode.lowercased().replacingOccurrences(of: "_", with: "-")
    if code == "zh-hant" || code.hasPrefix("zh-hant") || code == "zh-tw" || code.hasPrefix("zh-tw") || code == "zh-hk" || code.hasPrefix("zh-hk") || code == "zh-mo" || code.hasPrefix("zh-mo") {
        return "zh-hant"
    }
    if code == "zh" || code == "zh-cn" || code.hasPrefix("zh-hans") || code.hasPrefix("zh-") {
        return "zh-hans"
    }
    if code == "pt" || code.hasPrefix("pt-") {
        return "pt-br"
    }
    if code == "no" || code == "nn" || code.hasPrefix("nb") || code.hasPrefix("no-") {
        return "nb"
    }
    let primary = code.split(separator: "-").first.map(String.init) ?? code
    if tellomiLangPackLanguageCodes.contains(code) {
        return code
    }
    if tellomiLangPackLanguageCodes.contains(primary) {
        return primary
    }
    return "en"
}

public func tellomiBundledString(languageCode: String, key: String) -> String? {
    let code = tellomiCanonicalLangPackCode(languageCode)
    if let value = tellomiBundledLocalizationTable[code]?[key], !value.isEmpty {
        return value
    }
    if code != "en", let value = tellomiBundledLocalizationTable["en"]?[key], !value.isEmpty {
        return value
    }
    return nil
}

public func tellomiBundledStrings(languageCode: String) -> [String: String] {
    return tellomiBundledLocalizationTable[tellomiCanonicalLangPackCode(languageCode)] ?? [:]
}

